"use client";

import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { lineShadowTextDefaults, type LineShadowTextSpecProps } from "../generated/line-shadow-text.types";
import { cx } from "../utils/cx";

export interface LineShadowTextProps
  extends LineShadowTextSpecProps,
    Omit<HTMLAttributes<HTMLSpanElement>, keyof LineShadowTextSpecProps | "className" | "children"> {
  className?: string;
}

/**
 * Text with a diagonal line shadow behind it. The real text is rendered once; the shadow is an
 * aria-hidden, non-selectable copy that is clipped to a line pattern.
 */
export const LineShadowText = forwardRef<HTMLSpanElement, LineShadowTextProps>(function LineShadowText(
  { children, shadowColor = lineShadowTextDefaults.shadowColor, isPaused = lineShadowTextDefaults.isPaused, className, style, ...rest },
  ref,
) {
  return (
    <span
      {...rest}
      ref={ref}
      data-rdm-paused={isPaused || undefined}
      className={cx("rdm-line-shadow", className)}
      style={{ "--rdm-c": shadowColor, ...style } as CSSProperties}
    >
      {children}
      <span aria-hidden="true" className="rdm-line-shadow-layer">
        {children}
      </span>
    </span>
  );
});

// Generated by rdloom codegen from specs/line-shadow-text.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

/** Text with a diagonal line-pattern shadow behind it that slowly slides. The shadow copy is hidden from assistive technology. */
export interface LineShadowTextSpecProps {
  /**
   * The text.
   */
  children: string;
  /**
   * Colour of the shadow lines, any CSS colour.
   * @default "var(--rd-color-text-muted)"
   */
  shadowColor?: string;
  /**
   * Stops the animation and shows the text plainly. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
}

export const lineShadowTextDefaults = {
  shadowColor: "var(--rd-color-text-muted)",
  isPaused: false,
} as const;

export const lineShadowTextMeta = {
  "name": "LineShadowText",
  "version": "0.1.0",
  "status": "experimental",
  "role": "text"
} as const;
